package com.example.rokidkeyboardbridge;
public final class NavigationConversationChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("navigation conversation "+n);}
 public static int run(){n=0;
 String[][] intents={{"あとどれくらい？","remaining"},{"あと何分？","remaining"},{"目的地まであと何キロ","remaining"},{"次どっち？","next"},{"次はどちらですか","next"},{"もう一回","next"},{"次の案内","next"},{"そっちじゃない","clarify"},{"目的地が違う","destination"},{"道順のこと","route"},{"その前にコンビニ","stopover"},{"途中で東京駅に寄って","stopover"},{"やっぱり駅に行きたい","change"},{"やっぱり上尾駅へ変更して","change"}};
 for(String[] item:intents){ok(NavigationConversation.intent(item[0],true).equals(item[1]));ok(NavigationConversation.intent(item[0],false).isEmpty());}
 for(String s:new String[]{"天気は？","その前に説明して","次の予定を教えて","その前に計算して","やっぱり駅の歴史を知りたい"})ok(NavigationConversation.intent(s,true).isEmpty());
 ok(NavigationConversation.target("その前にコンビニ","stopover").equals("コンビニ"));ok(NavigationConversation.target("途中で東京駅に寄って。","stopover").equals("東京駅"));ok(NavigationConversation.target("やっぱり上尾駅へ変更して","change").equals("上尾駅"));
 ok(NavigationConversation.remaining(true,10000,9000,"10分","800 m").contains("10分、800 m"));for(long at:new long[]{0,11000,-1})ok(NavigationConversation.remaining(true,10000,at,"10分","800 m").contains("確認中"));ok(NavigationConversation.remaining(true,100000,1000,"10分","800 m").contains("確認中"));ok(NavigationConversation.remaining(false,10000,9000,"10分","800 m").contains("確認中"));ok(NavigationConversation.remaining(true,10000,9000,"","").contains("取得中"));
 NavigationVoiceSession session=new NavigationVoiceSession();session.interrupt(1000);ok(session.held(2000,false,false));ok(!session.held(4000,false,false));ok(session.held(4000,true,false));ok(session.held(4000,false,true));ok(session.admit("route|1|step1","右へ",1000,false));ok(!session.admit("route|1|step1","右へ",2000,false));ok(session.admit("route|1|step2","右へ",3000,false));ok(session.admit("route|1|step2","右へ",3100,true));ok(session.admit("route|2|step2","右へ",3200,false));ok(session.admit("route|2|step2","右へ",24000,false));
 ok(NavigationConversation.concise("<b>次の交差点を右です。</b>").equals("次の交差点を右です。"));ok(NavigationConversation.concise(null).isEmpty());
 NavigationTurnCue cue=new NavigationTurnCue();String landmark=cue.update("r|step1","中央交差点を右へ曲がる","30 m",10000,9900,10,true,true);ok(landmark.contains("中央交差点"));ok(landmark.contains("右"));ok(cue.update("r|step1","中央交差点を右へ曲がる","30 m",11000,10900,10,true,true).isEmpty());ok(cue.update("r|step2","斜め右へ進む","30 m",16000,15900,10,true,true).contains("斜め右"));ok(cue.update("r|step3","右へ曲がる","30 m",20000,19900,120,true,true).isEmpty());NavigationChangeConfirmation confirm=new NavigationChangeConfirmation();ok(!confirm.pending());confirm.arm("review_destination","上尾駅","r",1,1000);ok(confirm.pending());String[] approved=confirm.consume(true,true,"r",1,2000);ok(approved[0].equals("review_destination")&&approved[1].equals("上尾駅"));ok(!confirm.pending());ok(confirm.consume(true,true,"r",1,2100)[0].equals("empty"));
 confirm.arm("review_stopover","コンビニ","r",1,1000);ok(confirm.consume(false,true,"r",1,2000)[0].equals("cancel"));
 for(int condition=0;condition<5;condition++){confirm.arm("review_destination","駅","r",1,1000);ok(confirm.consume(true,condition!=0,condition==1?"other":"r",condition==2?2:1,condition==3?62000:condition==4?999:2000)[0].equals("stale"));ok(!confirm.pending());}
 confirm.arm("review_stopover","コンビニ","r",1,1000);confirm.clear();ok(!confirm.pending());
 ok(NavigationConversation.clarified("道順",61000,2000).equals("道順のこと"));ok(NavigationConversation.clarified("目的地",61000,2000).equals("目的地が違う"));ok(NavigationConversation.clarified("道順",61000,62000).equals("道順"));ok(NavigationConversation.clarified("道順",61000,999).equals("道順"));ok(NavigationConversation.clarified("道順",0,2000).equals("道順"));ok(NavigationConversation.clarified("天気は",61000,2000).equals("天気は"));return n;
 }
}
